// trayIconPNG generates a 36x36 (@2x 18pt) monochrome template PNG icon (envelope + AI bolt).
func trayIconPNG() []byte {
	const size = 36
	img := image.NewNRGBA(image.Rect(0, 0, size, size))

	setAA := func(x, y float64, alpha uint8) {
		ix, iy := int(math.Round(x)), int(math.Round(y))
		if ix < 0 || iy < 0 || ix >= size || iy >= size {
			return
		}
		cur := img.NRGBAAt(ix, iy)
		if alpha > cur.A {
			img.SetNRGBA(ix, iy, color.NRGBA{R: 0, G: 0, B: 0, A: alpha})
		}
	}

	drawSeg := func(x0, y0, x1, y1, radius float64) {
		dx, dy := x1-x0, y1-y0
		steps := int(math.Ceil(math.Hypot(dx, dy) * 3))
		if steps < 1 {
			steps = 1
		}
		for s := 0; s <= steps; s++ {
			t := float64(s) / float64(steps)
			cx, cy := x0+dx*t, y0+dy*t
			for py := int(math.Floor(cy - radius - 1)); py <= int(math.Ceil(cy+radius+1)); py++ {
				for px := int(math.Floor(cx - radius - 1)); px <= int(math.Ceil(cx+radius+1)); px++ {
					d := math.Hypot(float64(px)-cx, float64(py)-cy)
					if d <= radius+0.7 {
						a := 1.0
						if d > radius-0.4 {
							a = (radius + 0.7 - d) / 1.1
						}
						if a > 0 {
							if a > 1 {
								a = 1
							}
							setAA(float64(px), float64(py), uint8(a*255))
						}
					}
				}
			}
		}
	}

	// Rounded envelope outline
	r := 1.35
	drawSeg(5, 9, 31, 9, r)
	drawSeg(31, 9, 31, 27, r)
	drawSeg(31, 27, 5, 27, r)
	drawSeg(5, 27, 5, 9, r)
	// Envelope V flap
	drawSeg(6, 10, 18, 19.5, 1.2)
	drawSeg(30, 10, 18, 19.5, 1.2)
	// Small AI spark dot at top-right corner
	drawSeg(28.5, 6.0, 28.5, 6.0, 2.2)

	var buf bytes.Buffer
	_ = png.Encode(&buf, img)
	return buf.Bytes()
}
